(()=>{const g=new OffscreenCanvas(2,2).getContext('webgl2',{antialias:false}),p=g.createProgram();for(const [t,src]of [[g.VERTEX_SHADER,'#version 300 es\nvoid main(){gl_Position=vec4(float(gl_VertexID==1)*2.-1.,float(gl_VertexID==2)*2.-1.,0.,1.);}'],[g.FRAGMENT_SHADER,'#version 300 es\nprecision mediump float;uniform sampler2D image;out vec4 color;void main(){color=texture(image,gl_FragCoord.xy/vec2(2.));}']]){const s=g.createShader(t);g.shaderSource(s,src);g.compileShader(s);g.attachShader(p,s)}g.linkProgram(p);g.useProgram(p);const tex=g.createTexture();g.bindTexture(g.TEXTURE_2D,tex);for(const v of [g.TEXTURE_MIN_FILTER,g.TEXTURE_MAG_FILTER])g.texParameteri(g.TEXTURE_2D,v,g.NEAREST);const data=new Uint8Array([255,0,0,255,0,255,0,255,0,0,255,255,255,255,0,255]);g.texImage2D(g.TEXTURE_2D,0,g.RGBA,2,2,0,g.RGBA,g.UNSIGNED_BYTE,data);data.fill(0);const read=()=>{const b=new Uint8Array(16);g.readPixels(0,0,2,2,g.RGBA,g.UNSIGNED_BYTE,b);return Array.from(b)};g.drawArrays(g.TRIANGLES,0,3);const out=[read()];g.texSubImage2D(g.TEXTURE_2D,0,0,0,1,1,g.RGBA,g.UNSIGNED_BYTE,new Uint8Array([10,20,30,255]));g.drawArrays(g.TRIANGLES,0,3);out.push(read(),g.getError());return out})()
